const fs=require('node:fs'),path=require('node:path'),os=require('node:os');
try {
 const home=process.env.CODEX_HOME||path.join(os.homedir(),'.codex');
 const binding=JSON.parse(fs.readFileSync(path.join(home,'memory-loop/runtime.json'),'utf8'));
 const entry=path.join(binding.bundle,'runtime/codex.cjs');
 process.argv.splice(1,0,entry);
 require(entry);
} catch(e) { console.error('Memory Loop setup required: '+e.message); process.exitCode=1; }

